    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        c.initialize();

        assertTrue(c.owner() == address(this));

        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
